action.script:
set -euo pipefail
CACHE_DIR="$HOME/Library/Caches/com.hiimobapps.NotchAny/menu-bar-mirror"
BUNDLE="$CACHE_DIR/MenuBarMirrorHelper.app"
HELPER="$BUNDLE/Contents/MacOS/MenuBarMirrorHelper"
VERSION_FILE="$BUNDLE/Contents/Resources/source-version.txt"
SOURCE_FILE="$NOTCH_TEMP_DIR/menu-bar-mirror.swift"
mkdir -p "$CACHE_DIR"
rm -f "$CACHE_DIR/debug.log"
CURRENT_VERSION="$(/bin/cat "$VERSION_FILE" 2>/dev/null || true)"
if [[ ! -x "$HELPER" || "$CURRENT_VERSION" != "f13329c430b1" ]]; then
  mkdir -p "$BUNDLE/Contents/MacOS" "$BUNDLE/Contents/Resources/en.lproj" "$BUNDLE/Contents/Resources/zh-Hans.lproj"
  rm -f "$BUNDLE/Contents/source-version"
  cat > "$SOURCE_FILE" <<'MENU_BAR_MIRROR_SWIFT'
import AppKit
import ApplicationServices
import CoreGraphics
import Foundation
import ScreenCaptureKit

_ = NSApplication.shared

private let fileManager = FileManager.default
private let environment = ProcessInfo.processInfo.environment
private let isEnglish = (environment["NOTCH_LOCALE"] ?? "zh-Hans").lowercased().hasPrefix("en")
private let cacheDirectory = fileManager.homeDirectoryForCurrentUser
    .appendingPathComponent("Library/Caches/com.hiimobapps.NotchAny/menu-bar-mirror", isDirectory: true)
private let iconDirectory = cacheDirectory.appendingPathComponent("icons", isDirectory: true)
private let stateURL = cacheDirectory.appendingPathComponent("state.json")

private struct Permissions: Codable {
    let accessibility: Bool
    let screenCapture: Bool

    enum CodingKeys: String, CodingKey {
        case accessibility
        case screenCapture = "screen_capture"
    }
}

private struct MenuItemState: Codable {
    let id: String
    let bundleID: String
    let appName: String
    let title: String
    let visible: Bool
    let iconDataURL: String
    let width: Double
    let height: Double
    let ordinal: Int

    enum CodingKeys: String, CodingKey {
        case id
        case bundleID = "bundle_id"
        case appName = "app_name"
        case title
        case visible
        case iconDataURL = "icon_data_url"
        case width
        case height
        case ordinal
    }
}

private struct WidgetState: Codable {
    let status: String
    let permissions: Permissions
    let items: [MenuItemState]
    let message: String?
    let lastActionOK: Bool?
    let pressedID: String?

    enum CodingKeys: String, CodingKey {
        case status
        case permissions
        case items
        case message
        case lastActionOK = "last_action_ok"
        case pressedID = "pressed_id"
    }
}

private struct PressPayload {
    let id: String?
    let bundleID: String
    let ordinal: Int
}

private struct Candidate {
    let element: AXUIElement
    let app: NSRunningApplication
    let bundleID: String
    let appName: String
    let title: String
    let frame: CGRect
    let visible: Bool
    let ordinal: Int

    var id: String { "\(bundleID)#\(ordinal)" }
}

private final class ShareableContentBox: @unchecked Sendable {
    var content: SCShareableContent?
    var error: Error?
}

private final class CapturedImageBox: @unchecked Sendable {
    var image: CGImage?
    var error: Error?
}

private func localized(_ chinese: String, _ english: String) -> String {
    isEnglish ? english : chinese
}

private func copyAttribute(_ element: AXUIElement, _ name: String) -> CFTypeRef? {
    var value: CFTypeRef?
    guard AXUIElementCopyAttributeValue(element, name as CFString, &value) == .success else {
        return nil
    }
    return value
}

private func stringAttribute(_ element: AXUIElement, _ name: String) -> String {
    copyAttribute(element, name) as? String ?? ""
}

private func boolAttribute(_ element: AXUIElement, _ name: String) -> Bool? {
    copyAttribute(element, name) as? Bool
}

private func pointAttribute(_ element: AXUIElement) -> CGPoint {
    guard let rawValue = copyAttribute(element, kAXPositionAttribute),
          CFGetTypeID(rawValue) == AXValueGetTypeID() else {
        return .zero
    }
    var value = CGPoint.zero
    _ = AXValueGetValue(rawValue as! AXValue, .cgPoint, &value)
    return value
}

private func sizeAttribute(_ element: AXUIElement) -> CGSize {
    guard let rawValue = copyAttribute(element, kAXSizeAttribute),
          CFGetTypeID(rawValue) == AXValueGetTypeID() else {
        return .zero
    }
    var value = CGSize.zero
    _ = AXValueGetValue(rawValue as! AXValue, .cgSize, &value)
    return value
}

private func isSystemApplication(_ app: NSRunningApplication) -> Bool {
    if let bundleID = app.bundleIdentifier, bundleID.hasPrefix("com.apple.") {
        return true
    }
    guard let path = app.bundleURL?.standardizedFileURL.path else { return false }
    return path.hasPrefix("/System/") || path.hasPrefix("/usr/libexec/")
}

private func menuBarSafeAreas() -> [CGRect] {
    NSScreen.screens.flatMap { screen -> [CGRect] in
        guard let rawID = screen.deviceDescription[NSDeviceDescriptionKey("NSScreenNumber")] as? NSNumber else {
            return []
        }
        let displayBounds = CGDisplayBounds(CGDirectDisplayID(rawID.uint32Value))
        if #available(macOS 12.0, *),
           let left = screen.auxiliaryTopLeftArea,
           let right = screen.auxiliaryTopRightArea,
           left.width > 0,
           right.width > 0 {
            let height = max(left.height, right.height)
            return [
                CGRect(x: left.minX, y: displayBounds.minY, width: left.width, height: height),
                CGRect(x: right.minX, y: displayBounds.minY, width: right.width, height: height),
            ]
        }
        return [CGRect(x: displayBounds.minX, y: displayBounds.minY, width: displayBounds.width, height: 40)]
    }
}

private func menuCandidates(bundleID filterBundleID: String? = nil) -> [Candidate] {
    let safeAreas = menuBarSafeAreas()
    var candidates: [Candidate] = []
    var seen = Set<String>()

    for app in NSWorkspace.shared.runningApplications {
        guard !app.isTerminated, !isSystemApplication(app) else { continue }
        let bundleID = app.bundleIdentifier ?? "pid.\(app.processIdentifier)"
        if let filterBundleID, bundleID != filterBundleID { continue }

        let appElement = AXUIElementCreateApplication(app.processIdentifier)
        guard let rawMenuBar = copyAttribute(appElement, kAXExtrasMenuBarAttribute),
              CFGetTypeID(rawMenuBar) == AXUIElementGetTypeID() else {
            continue
        }
        let menuBar = rawMenuBar as! AXUIElement
        guard let children = copyAttribute(menuBar, kAXChildrenAttribute) as? [AXUIElement] else {
            continue
        }

        for (ordinal, element) in children.enumerated() {
            guard stringAttribute(element, kAXRoleAttribute) == kAXMenuBarItemRole else { continue }
            let origin = pointAttribute(element)
            let size = sizeAttribute(element)
            let frame = CGRect(origin: origin, size: size)
            let visible = size.width > 0 && size.height > 0 && safeAreas.contains(where: { $0.contains(frame) })
            let title = [
                stringAttribute(element, kAXTitleAttribute),
                stringAttribute(element, kAXDescriptionAttribute),
                stringAttribute(element, kAXValueAttribute),
            ].first(where: { !$0.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty }) ?? ""
            let dedupeKey = [
                bundleID,
                String(ordinal),
                String(Int(frame.origin.x.rounded())),
                String(Int(frame.origin.y.rounded())),
                String(Int(frame.width.rounded())),
                String(Int(frame.height.rounded())),
                title,
            ].joined(separator: "|")
            guard seen.insert(dedupeKey).inserted else { continue }
            candidates.append(Candidate(
                element: element,
                app: app,
                bundleID: bundleID,
                appName: app.localizedName ?? bundleID,
                title: title,
                frame: frame,
                visible: visible,
                ordinal: ordinal
            ))
        }
    }

    let sortedCandidates = candidates.sorted { lhs, rhs in
        if lhs.visible != rhs.visible { return lhs.visible }
        if lhs.visible {
            if abs(lhs.frame.midY - rhs.frame.midY) > 20 { return lhs.frame.minY < rhs.frame.minY }
            return lhs.frame.minX < rhs.frame.minX
        }
        let nameOrder = lhs.appName.localizedStandardCompare(rhs.appName)
        if nameOrder != .orderedSame { return nameOrder == .orderedAscending }
        return lhs.ordinal < rhs.ordinal
    }
    if environment["MENU_BAR_MIRROR_DEBUG"] == "1" {
        for candidate in sortedCandidates {
            var rawActions: CFArray?
            let actionResult = AXUIElementCopyActionNames(candidate.element, &rawActions)
            let actions = actionResult == .success ? (rawActions as? [String] ?? []) : []
            fputs(
                "AX \(candidate.appName) x=\(candidate.frame.minX) w=\(candidate.frame.width) visible=\(candidate.visible) actions=\(actions)\n",
                stderr
            )
        }
    }
    return sortedCandidates
}

private func pngDataURL(_ data: Data) -> String {
    "data:image/png;base64," + data.base64EncodedString()
}

private func safeFileComponent(_ value: String) -> String {
    value.unicodeScalars.map { scalar in
        CharacterSet.alphanumerics.contains(scalar) ? String(scalar) : "_"
    }.joined()
}

private func statusItemWindows() -> [SCWindow] {
    let box = ShareableContentBox()
    let semaphore = DispatchSemaphore(value: 0)
    Task {
        do {
            box.content = try await SCShareableContent.excludingDesktopWindows(
                false,
                onScreenWindowsOnly: false
            )
        } catch {
            box.error = error
        }
        semaphore.signal()
    }
    guard semaphore.wait(timeout: .now() + 6) == .success, let content = box.content else {
        if environment["MENU_BAR_MIRROR_DEBUG"] == "1" {
            fputs("SC CONTENT error=\(String(describing: box.error))\n", stderr)
        }
        return []
    }
    let windows = content.windows.filter { window in
        guard window.owningApplication?.bundleIdentifier == "com.apple.controlcenter" else {
            return false
        }
        let frame = window.frame
        let title = window.title ?? ""
        return frame.minY < 40 &&
            frame.height >= 20 && frame.height <= 40 &&
            frame.width >= 10 && frame.width <= 200 &&
            !title.hasPrefix("Clock") &&
            !title.hasPrefix("BentoBox")
    }
    if environment["MENU_BAR_MIRROR_DEBUG"] == "1" {
        fputs("SC CONTENT statusWindows=\(windows.count) totalWindows=\(content.windows.count)\n", stderr)
    }
    return windows
}

private func matchStatusWindows(candidates: [Candidate], windows: [SCWindow]) -> [String: SCWindow] {
    var matches: [String: SCWindow] = [:]
    var unusedWindowIDs = Set(windows.map(\.windowID))
    for candidate in candidates.sorted(by: { $0.frame.midX < $1.frame.midX }) {
        let match = windows
            .filter { unusedWindowIDs.contains($0.windowID) }
            .map { window in (window, abs(window.frame.midX - candidate.frame.midX)) }
            .filter { $0.1 <= 8 }
            .min { lhs, rhs in lhs.1 < rhs.1 }
        guard let (window, _) = match else { continue }
        matches[candidate.id] = window
        unusedWindowIDs.remove(window.windowID)
        if environment["MENU_BAR_MIRROR_DEBUG"] == "1" {
            fputs(
                "SC \(candidate.appName) id=\(window.windowID) x=\(window.frame.minX) w=\(window.frame.width) onScreen=\(window.isOnScreen)\n",
                stderr
            )
        }
    }
    return matches
}

private func captureWindowWithSystemTool(_ window: SCWindow, outputURL: URL) -> Data? {
    try? fileManager.removeItem(at: outputURL)
    let process = Process()
    process.executableURL = URL(fileURLWithPath: "/usr/sbin/screencapture")
    process.arguments = ["-x", "-o", "-tpng", "-l\(window.windowID)", outputURL.path]
    process.standardOutput = FileHandle.nullDevice
    process.standardError = FileHandle.nullDevice
    do {
        try process.run()
        process.waitUntilExit()
        guard process.terminationStatus == 0,
              let data = try? Data(contentsOf: outputURL),
              !data.isEmpty else {
            return nil
        }
        return data
    } catch {
        return nil
    }
}

private func captureMenuItem(_ candidate: Candidate, window: SCWindow) -> String? {
    let filename = safeFileComponent(candidate.id) + ".png"
    let outputURL = iconDirectory.appendingPathComponent(filename)

    let box = CapturedImageBox()
    let semaphore = DispatchSemaphore(value: 0)
    Task {
        let configuration = SCStreamConfiguration()
        configuration.width = max(1, Int(window.frame.width * 2))
        configuration.height = max(1, Int(window.frame.height * 2))
        configuration.showsCursor = false
        configuration.captureResolution = .best
        let filter = SCContentFilter(desktopIndependentWindow: window)
        do {
            box.image = try await SCScreenshotManager.captureImage(
                contentFilter: filter,
                configuration: configuration
            )
        } catch {
            box.error = error
        }
        semaphore.signal()
    }
    if semaphore.wait(timeout: .now() + 4) == .success,
       let image = box.image,
       let data = NSBitmapImageRep(cgImage: image).representation(using: .png, properties: [:]),
       !data.isEmpty {
        try? data.write(to: outputURL, options: .atomic)
        return pngDataURL(data)
    }
    if environment["MENU_BAR_MIRROR_DEBUG"] == "1" {
        fputs("SC CAPTURE \(candidate.appName) error=\(String(describing: box.error))\n", stderr)
    }
    if let data = captureWindowWithSystemTool(window, outputURL: outputURL) {
        return pngDataURL(data)
    }
    return nil
}

private func applicationIcon(_ candidate: Candidate) -> String {
    let image: NSImage
    if let path = candidate.app.bundleURL?.path {
        image = NSWorkspace.shared.icon(forFile: path)
    } else {
        image = NSImage(systemSymbolName: "app.fill", accessibilityDescription: nil) ?? NSImage()
    }

    let pixels = 64
    guard let bitmap = NSBitmapImageRep(
        bitmapDataPlanes: nil,
        pixelsWide: pixels,
        pixelsHigh: pixels,
        bitsPerSample: 8,
        samplesPerPixel: 4,
        hasAlpha: true,
        isPlanar: false,
        colorSpaceName: .deviceRGB,
        bytesPerRow: 0,
        bitsPerPixel: 0
    ) else { return "" }

    bitmap.size = NSSize(width: 32, height: 32)
    NSGraphicsContext.saveGraphicsState()
    NSGraphicsContext.current = NSGraphicsContext(bitmapImageRep: bitmap)
    NSColor.clear.setFill()
    NSRect(x: 0, y: 0, width: 32, height: 32).fill()
    image.draw(
        in: NSRect(x: 2, y: 2, width: 28, height: 28),
        from: .zero,
        operation: .sourceOver,
        fraction: 1,
        respectFlipped: true,
        hints: [.interpolation: NSImageInterpolation.high]
    )
    NSGraphicsContext.restoreGraphicsState()
    guard let data = bitmap.representation(using: .png, properties: [:]) else { return "" }
    return pngDataURL(data)
}

private func permissions() -> Permissions {
    Permissions(
        accessibility: AXIsProcessTrusted(),
        screenCapture: CGPreflightScreenCaptureAccess()
    )
}

private func makeState(message: String? = nil, lastActionOK: Bool? = nil, pressedID: String? = nil) -> WidgetState {
    let preflightPermissions = permissions()
    guard preflightPermissions.accessibility else {
        return WidgetState(
            status: "permission_required",
            permissions: preflightPermissions,
            items: [],
            message: message ?? localized(
                "需要辅助功能权限才能读取和点击菜单栏项目",
                "Accessibility permission is required to read and click menu bar items"
            ),
            lastActionOK: lastActionOK,
            pressedID: pressedID
        )
    }

    try? fileManager.createDirectory(at: iconDirectory, withIntermediateDirectories: true)
    var captureFailed = false
    let candidates = menuCandidates()
    let windows = preflightPermissions.screenCapture ? statusItemWindows() : []
    let windowMatches = matchStatusWindows(candidates: candidates, windows: windows)
    let hasVisibleCandidates = candidates.contains(where: \.visible)
    var capturedIcons: [String: String] = [:]
    var screenCaptureReady = preflightPermissions.screenCapture
    if screenCaptureReady && hasVisibleCandidates {
        for probeCandidate in candidates where probeCandidate.visible {
            guard let probeWindow = windowMatches[probeCandidate.id] else { continue }
            if let captured = captureMenuItem(probeCandidate, window: probeWindow) {
                capturedIcons[probeCandidate.id] = captured
                break
            }
        }
        if capturedIcons.isEmpty {
            screenCaptureReady = false
        }
    }
    let currentPermissions = Permissions(
        accessibility: preflightPermissions.accessibility,
        screenCapture: screenCaptureReady
    )
    let items = candidates.map { candidate -> MenuItemState in
        let captured = capturedIcons[candidate.id] ?? (screenCaptureReady && candidate.visible
            ? windowMatches[candidate.id].flatMap {
                captureMenuItem(candidate, window: $0)
            }
            : nil)
        if screenCaptureReady && candidate.visible && captured == nil { captureFailed = true }
        let icon = captured ?? applicationIcon(candidate)
        return MenuItemState(
            id: candidate.id,
            bundleID: candidate.bundleID,
            appName: candidate.appName,
            title: candidate.title,
            visible: candidate.visible,
            iconDataURL: icon,
            width: candidate.visible ? max(18, candidate.frame.width) : 24,
            height: candidate.visible ? max(18, candidate.frame.height) : 24,
            ordinal: candidate.ordinal
        )
    }

    let resolvedMessage: String?
    if let message {
        resolvedMessage = message
    } else if !screenCaptureReady {
        resolvedMessage = localized(
            "需要为菜单栏镜像辅助程序授权屏幕录制；授权后请重启 NotchAny",
            "Allow screen recording for Menu Bar Mirror Helper, then restart NotchAny"
        )
    } else if captureFailed {
        resolvedMessage = localized(
            "部分菜单栏图标截图失败，已使用应用图标",
            "Some menu bar icons could not be captured; app icons are shown instead"
        )
    } else {
        resolvedMessage = nil
    }

    return WidgetState(
        status: "ok",
        permissions: currentPermissions,
        items: items,
        message: resolvedMessage,
        lastActionOK: lastActionOK,
        pressedID: pressedID
    )
}

private func saveState(_ state: WidgetState) {
    guard let data = try? JSONEncoder().encode(state) else { return }
    try? fileManager.createDirectory(at: cacheDirectory, withIntermediateDirectories: true)
    let temporaryURL = stateURL.appendingPathExtension("tmp")
    do {
        try data.write(to: temporaryURL, options: .atomic)
        if fileManager.fileExists(atPath: stateURL.path) {
            _ = try? fileManager.replaceItemAt(stateURL, withItemAt: temporaryURL)
        } else {
            try fileManager.moveItem(at: temporaryURL, to: stateURL)
        }
    } catch {
        try? fileManager.removeItem(at: temporaryURL)
    }
}

private func cachedState(message: String, lastActionOK: Bool, pressedID: String?) -> WidgetState {
    if let data = try? Data(contentsOf: stateURL),
       let existing = try? JSONDecoder().decode(WidgetState.self, from: data) {
        let preflightPermissions = permissions()
        let cachedPermissions = Permissions(
            accessibility: preflightPermissions.accessibility,
            screenCapture: preflightPermissions.screenCapture && existing.permissions.screenCapture
        )
        return WidgetState(
            status: existing.status,
            permissions: cachedPermissions,
            items: existing.items,
            message: message,
            lastActionOK: lastActionOK,
            pressedID: pressedID
        )
    }
    return makeState(message: message, lastActionOK: lastActionOK, pressedID: pressedID)
}

private func performPress(_ payload: PressPayload) -> WidgetState {
    guard AXIsProcessTrusted() else {
        return makeState(
            message: localized(
                "需要辅助功能权限才能点击菜单栏项目",
                "Accessibility permission is required to click menu bar items"
            ),
            lastActionOK: false,
            pressedID: payload.id
        )
    }
    let candidates = menuCandidates(bundleID: payload.bundleID)
    guard let candidate = candidates.first(where: { $0.ordinal == payload.ordinal }) else {
        return cachedState(
            message: localized(
                "项目已退出或位置已变化，请刷新后重试",
                "The item exited or moved; refresh and try again"
            ),
            lastActionOK: false,
            pressedID: payload.id
        )
    }
    let selectedBefore = boolAttribute(candidate.element, kAXSelectedAttribute)
    let result = AXUIElementPerformAction(candidate.element, kAXPressAction as CFString)
    let selectedAfter = boolAttribute(candidate.element, kAXSelectedAttribute)
    if environment["MENU_BAR_MIRROR_DEBUG"] == "1" {
        fputs(
            "PRESS \(candidate.appName) result=\(result.rawValue) selectedBefore=\(String(describing: selectedBefore)) selectedAfter=\(String(describing: selectedAfter))\n",
            stderr
        )
    }
    let selectionChanged = selectedBefore != nil && selectedAfter != nil && selectedBefore != selectedAfter
    guard result == .success || (result == .cannotComplete && selectionChanged) else {
        return cachedState(
            message: localized(
                "无法打开 \(candidate.appName) 的菜单栏项目",
                "Could not open \(candidate.appName)'s menu bar item"
            ),
            lastActionOK: false,
            pressedID: payload.id
        )
    }
    return cachedState(message: "", lastActionOK: true, pressedID: payload.id)
}

private func requestAccessibility() -> WidgetState {
    let options = [kAXTrustedCheckOptionPrompt.takeUnretainedValue() as String: true] as CFDictionary
    _ = AXIsProcessTrustedWithOptions(options)
    return makeState(message: AXIsProcessTrusted() ? nil : localized(
        "授权后请重新打开组件；如仍未生效，请重启 NotchAny",
        "Reopen the widget after granting access; restart NotchAny if needed"
    ))
}

private func requestScreenCapture() -> WidgetState {
    _ = CGRequestScreenCaptureAccess()
    return makeState(message: localized(
        "授权后请重启 NotchAny 以显示真实菜单栏图标",
        "Restart NotchAny after granting access to show the actual menu bar icons"
    ))
}

private func decodePressPayload(_ rawPayload: String) -> PressPayload? {
    guard let data = rawPayload.data(using: .utf8),
          let object = try? JSONSerialization.jsonObject(with: data),
          let dictionary = object as? [String: Any],
          let bundleID = dictionary["bundle_id"] as? String else {
        return nil
    }
    let ordinal: Int?
    if let value = dictionary["ordinal"] as? NSNumber {
        ordinal = value.intValue
    } else if let value = dictionary["ordinal"] as? String {
        ordinal = Int(value)
    } else {
        ordinal = nil
    }
    guard let ordinal else { return nil }
    return PressPayload(id: dictionary["id"] as? String, bundleID: bundleID, ordinal: ordinal)
}

private func decodePressEvent(_ event: String) -> PressPayload? {
    let parts = event.split(separator: ":", maxSplits: 2, omittingEmptySubsequences: false)
    guard parts.count == 3,
          parts[0] == "press",
          let ordinal = Int(parts[1]),
          !parts[2].isEmpty else {
        return nil
    }
    let bundleID = String(parts[2])
    return PressPayload(id: "\(bundleID)#\(ordinal)", bundleID: bundleID, ordinal: ordinal)
}

private func emit(_ state: WidgetState) {
    let encoder = JSONEncoder()
    encoder.outputFormatting = [.withoutEscapingSlashes]
    if let data = try? encoder.encode(state) {
        FileHandle.standardOutput.write(data)
        FileHandle.standardOutput.write(Data("\n".utf8))
    }
}

try? fileManager.createDirectory(at: cacheDirectory, withIntermediateDirectories: true)

private let event = environment["NOTCH_WIDGET_EVENT"] ?? "refresh"
private let state: WidgetState
switch event {
case let event where event == "press" || event.hasPrefix("press:"):
    let rawPayload = environment["NOTCH_WIDGET_PAYLOAD"] ?? "{}"
    if let payload = decodePressPayload(rawPayload) ?? decodePressEvent(event) {
        state = performPress(payload)
    } else {
        state = cachedState(
            message: localized(
                "点击参数无效，请刷新后重试",
                "The click target is invalid; refresh and try again"
            ),
            lastActionOK: false,
            pressedID: nil
        )
    }
case "request_accessibility":
    state = requestAccessibility()
case "request_screen_capture":
    state = requestScreenCapture()
default:
    state = makeState()
    saveState(state)
}
emit(state)
MENU_BAR_MIRROR_SWIFT
  cat > "$BUNDLE/Contents/Info.plist" <<'MENU_BAR_MIRROR_PLIST'
<?xml version="1.0" encoding="UTF-8"?>
<!DOCTYPE plist PUBLIC "-//Apple//DTD PLIST 1.0//EN" "https://www.apple.com/DTDs/PropertyList-1.0.dtd">
<plist version="1.0"><dict>
<key>CFBundleIdentifier</key><string>com.hiimobapps.NotchAny.MenuBarMirror</string>
<key>CFBundleName</key><string>Menu Bar Mirror Helper</string>
<key>CFBundleDisplayName</key><string>Menu Bar Control Center Helper</string>
<key>CFBundleExecutable</key><string>MenuBarMirrorHelper</string>
<key>CFBundlePackageType</key><string>APPL</string>
<key>CFBundleShortVersionString</key><string>1.0</string>
<key>CFBundleVersion</key><string>4046662084</string>
<key>LSUIElement</key><true/>
<key>NSAccessibilityUsageDescription</key><string>Read and click non-system menu bar items.</string>
<key>NSScreenCaptureUsageDescription</key><string>Show the actual icons and text currently displayed in the menu bar.</string>
