widget.css:
:root {
  color-scheme: dark;
  font-family: -apple-system, BlinkMacSystemFont, "PingFang SC", "SF Pro Text", sans-serif;
  container-type: size;
}
* { box-sizing: border-box; }
html, body {
  width: 100%;
  height: 100%;
  margin: 0;
  overflow: hidden;
  background: transparent;
  -webkit-user-select: none;
  user-select: none;
}
button { font: inherit; }
.panel {
  position: relative;
  width: 100%;
  height: 100%;
  padding: 6px 7px;
  border-radius: 13px;
  background: rgba(19, 20, 23, .97);
  box-shadow: inset 0 0 0 1px rgba(255, 255, 255, .11), 0 5px 18px rgba(0, 0, 0, .24);
  color: rgba(255, 255, 255, .94);
  display: flex;
  flex-direction: column;
  gap: 4px;
  overflow: hidden;
}
svg {
  fill: none;
  stroke: currentColor;
  stroke-width: 1.8;
  stroke-linecap: round;
  stroke-linejoin: round;
}
.permission,
.notice {
  display: flex;
  align-items: center;
}
.icon-button {
  position: absolute;
  top: 7px;
  right: 7px;
  z-index: 3;
  width: 21px;
  height: 21px;
  padding: 4px;
  border: 0;
  border-radius: 6px;
  background: transparent;
  color: rgba(255, 255, 255, .48);
  cursor: pointer;
  flex: 0 0 auto;
}
.icon-button svg { width: 100%; height: 100%; }
.icon-button:hover { background: rgba(255, 255, 255, .10); color: rgba(255, 255, 255, .9); }
.icon-button:active { background: rgba(255, 255, 255, .17); }
.icon-button.busy svg { animation: spin .7s linear infinite; }
@keyframes spin { to { transform: rotate(360deg); } }
.permission,
.notice {
  min-width: 0;
  min-height: 22px;
  gap: 6px;
  padding: 3px 5px;
  border-radius: 6px;
  font-size: 8.5px;
}
.permission {
  color: #fde68a;
  background: rgba(251, 191, 36, .10);
}
.permission > svg { width: 12px; height: 12px; flex: 0 0 auto; }
.permission span,
.notice span {
  min-width: 0;
  flex: 1 1 auto;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.permission button,
.notice button {
  height: 17px;
  padding: 0 6px;
  border: 0;
  border-radius: 5px;
  background: rgba(255, 255, 255, .14);
  color: rgba(255, 255, 255, .9);
  font-size: 8px;
  cursor: pointer;
  flex: 0 0 auto;
}
.permission button:hover,
.notice button:hover { background: rgba(255, 255, 255, .22); }
.notice {
  color: #fcd34d;
  background: rgba(245, 158, 11, .09);
}
.items {
  flex: 1 1 auto;
  min-height: 0;
  overflow-x: auto;
  overflow-y: hidden;
  scrollbar-width: none;
  align-items: center;
  display: flex;
  flex-wrap: nowrap;
  gap: 4px;
  margin-right: 25px;
  padding: 1px 0;
  scroll-snap-type: x mandatory;
}
.items::-webkit-scrollbar { display: none; }
.menu-item {
  position: relative;
  flex: 0 0 var(--item-width, calc((100% - 12px) / 4));
  height: 30px;
  min-width: 0;
  max-width: none;
  padding: 3px 2px;
  border: 0;
  border-radius: 6px;
  background: rgba(255, 255, 255, .035);
  color: #fff;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  overflow: hidden;
  scroll-snap-align: start;
}
.items.multi-row {
  align-content: flex-start;
  align-items: flex-start;
  flex-wrap: wrap;
  overflow-x: hidden;
  overflow-y: auto;
  scroll-snap-type: none;
}
.items.multi-row .menu-item { scroll-snap-align: none; }
.menu-item:hover { background: rgba(255, 255, 255, .12); }
.menu-item:active { background: rgba(125, 211, 252, .18); transform: translateY(1px); }
.menu-item[disabled] { opacity: .45; cursor: default; transform: none; }
.menu-item img {
  display: block;
  max-width: 100%;
  max-height: 24px;
  object-fit: contain;
  image-rendering: auto;
}
.menu-item.hidden-item {
  background: rgba(255, 255, 255, .05);
}
.hidden-item img { width: 22px; height: 22px; opacity: .72; }
.hidden-mark {
  position: absolute;
  right: 2px;
  bottom: 2px;
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: rgba(19, 20, 23, .92);
  color: rgba(255, 255, 255, .66);
  padding: 1px;
}
.empty {
  flex: 1 1 auto;
  min-height: 0;
  color: rgba(255, 255, 255, .38);
  font-size: 9px;
  display: flex;
  align-items: center;
  justify-content: center;
  text-align: center;
}
.toast {
  position: absolute;
  left: 9px;
  right: 9px;
  bottom: 7px;
  min-height: 22px;
  padding: 5px 7px;
  border-radius: 6px;
  background: rgba(35, 37, 42, .98);
  box-shadow: 0 3px 12px rgba(0, 0, 0, .38), inset 0 0 0 1px rgba(255, 255, 255, .12);
  color: rgba(255, 255, 255, .86);
  font-size: 8.5px;
  line-height: 1.35;
  text-align: center;
  pointer-events: none;
}
[hidden] { display: none !important; }
@container (max-width: 190px) {
  .panel { padding-left: 7px; padding-right: 7px; }
  .menu-item { max-width: 86px; }
  .menu-item img { max-width: 78px; }
}

widget.javascript:
const $ = id => document.getElementById(id);
const FALLBACK_REFRESH_MS = 10000;
let timer = 0;
let toastTimer = 0;
let refreshPromise = null;
let pressing = false;
let requestingPermission = false;
let multiRowLayout = null;
const t = key => (window.__notchWidget.i18n || {})[key] ?? key;

function applyI18n() {
  const refresh = $('refresh');
  refresh.title = t('refresh');
  refresh.setAttribute('aria-label', t('refresh'));
  $('permissionText').textContent = t('system_permission_required');
  $('permissionButton').textContent = t('grant');
  $('captureButton').textContent = t('grant');
  $('empty').textContent = t('no_items');
}

function showToast(message, timeout = 2600) {
  clearTimeout(toastTimer);
  const toast = $('toast');
  if (!message) {
    toast.hidden = true;
    return;
  }
  toast.textContent = message;
  toast.hidden = false;
  toastTimer = setTimeout(() => { toast.hidden = true; }, timeout);
}

function itemLabel(item) {
  const detail = item.title && item.title !== item.app_name ? ' · ' + item.title : '';
  return item.app_name + detail + (item.visible ? '' : ' · ' + t('hidden'));
}

function hiddenMark() {
  const mark = document.createElementNS('http://www.w3.org/2000/svg', 'svg');
  mark.setAttribute('class', 'hidden-mark');
  mark.setAttribute('viewBox', '0 0 24 24');
  mark.setAttribute('aria-hidden', 'true');
  mark.innerHTML = '<path d="M3 3l18 18M10.6 10.7a2 2 0 0 0 2.7 2.7M9.9 4.3A10.7 10.7 0 0 1 12 4c5.4 0 9 5 9 5a17 17 0 0 1-2.5 2.9M6.6 6.7C4.4 8.2 3 10 3 10s3.6 5 9 5c.7 0 1.4-.1 2-.2"/>';
  return mark;
}

function updateItem(button, item) {
  const label = itemLabel(item);
  const image = button.querySelector('img');
  const mark = button.querySelector('.hidden-mark');
  const source = item.icon_data_url || '';

  button._menuItem = item;
  button.dataset.itemId = item.id;
  button.classList.toggle('hidden-item', !item.visible);
  button.title = label;
  button.setAttribute('aria-label', label);

  if (button._iconSource !== source) {
    button._iconSource = source;
    image.src = source;
  }
  image.style.height = item.visible
    ? Math.min(24, Math.max(18, Number(item.height || 22))) + 'px'
    : '22px';

  if (!item.visible && !mark) button.appendChild(hiddenMark());
  if (item.visible && mark) mark.remove();
}

async function pressItem(item, button) {
  if (pressing) return;
  pressing = true;
  button.disabled = true;
  try {
    if (refreshPromise) await refreshPromise;
    const eventName = `press:${item.ordinal}:${item.bundle_id}`;
    const result = await notchany.invoke(eventName, {
      id: item.id,
      bundle_id: item.bundle_id,
      ordinal: item.ordinal
    });
    if (!result?.ok) {
      showToast(result?.error?.message || t('click_failed'));
      return;
    }
    const state = result.state || {};
    if (state.last_action_ok === false) showToast(state.message || t('open_failed'));
  } finally {
    button.disabled = false;
    pressing = false;
  }
}

function createItem(item) {
  const button = document.createElement('button');
  button.className = 'menu-item';
  button.type = 'button';
  const image = document.createElement('img');
  image.alt = '';
  image.draggable = false;
  button.appendChild(image);
  button.addEventListener('click', () => {
    if (button._menuItem) pressItem(button._menuItem, button);
  });
  updateItem(button, item);
  return button;
}

function updateResponsiveLayout() {
  const items = $('items');
  const nextMultiRow = document.documentElement.clientHeight >= 96;
  const responsiveColumns = Math.floor((items.clientWidth + 4) / 50);
  const columns = nextMultiRow
    ? Math.max(2, responsiveColumns)
    : Math.max(4, responsiveColumns);
  const itemWidth = Math.max(24, (items.clientWidth - (columns - 1) * 4) / columns);

  items.classList.toggle('multi-row', nextMultiRow);
  items.style.setProperty('--item-width', itemWidth + 'px');
  if (multiRowLayout !== null && multiRowLayout !== nextMultiRow) {
    items.scrollLeft = 0;
    items.scrollTop = 0;
  }
  multiRowLayout = nextMultiRow;
}

function reconcileItems(items) {
  const container = $('items');
  const previousPositions = new Map(
    Array.from(container.children, node => [node.dataset.itemId, node.getBoundingClientRect()])
  );
  const existing = new Map(
    Array.from(container.children, node => [node.dataset.itemId, node])
  );
  const scrollLeft = container.scrollLeft;
  const scrollTop = container.scrollTop;
  const ordered = items.map(item => {
    const button = existing.get(item.id) || createItem(item);
    existing.delete(item.id);
    updateItem(button, item);
    return button;
  });

  existing.forEach(button => button.remove());
  container.append(...ordered);
  container.scrollLeft = scrollLeft;
  container.scrollTop = scrollTop;
  updateResponsiveLayout();

  if (window.matchMedia('(prefers-reduced-motion: reduce)').matches) return;
  requestAnimationFrame(() => {
    ordered.forEach(button => {
      const previous = previousPositions.get(button.dataset.itemId);
      if (!previous) return;
      const current = button.getBoundingClientRect();
      const x = previous.left - current.left;
      const y = previous.top - current.top;
      if (Math.abs(x) < 1 && Math.abs(y) < 1) return;
      button.animate(
        [{ transform: `translate(${x}px, ${y}px)` }, { transform: 'translate(0, 0)' }],
        { duration: 180, easing: 'cubic-bezier(.2,.8,.2,1)' }
      );
    });
  });
}

function render(result) {
  if (!result?.ok || !result.state) return false;
  const state = result.state;
  const items = Array.isArray(state.items) ? state.items : [];
  const permissions = state.permissions || {};

  $('permission').hidden = permissions.accessibility !== false;
  $('notice').hidden = permissions.accessibility === false || permissions.screen_capture !== false;
  $('items').hidden = permissions.accessibility === false;
  $('empty').hidden = permissions.accessibility === false || items.length !== 0;

  if (permissions.accessibility === false) {
    $('permissionText').textContent = state.message || t('accessibility_required');
    $('items').replaceChildren();
    return true;
  }

  if (permissions.screen_capture === false) {
    const captureMessage = state.message || t('screen_capture_required');
    $('noticeText').textContent = captureMessage;
    $('notice').title = captureMessage;
  }

  reconcileItems(items);
  if (state.last_action_ok === false && state.message) showToast(state.message);
  return true;
}

async function refresh() {
  if (!notchany.visible || pressing) return;
  if (refreshPromise) return refreshPromise;
  const button = $('refresh');
  button.classList.add('busy');
  refreshPromise = (async () => {
    const result = await notchany.invoke('refresh', null);
    if (!render(result) && !notchany.state) showToast(t('read_failed'));
  })();
  try {
    await refreshPromise;
  } finally {
    refreshPromise = null;
    button.classList.remove('busy');
  }
}

async function requestPermission(eventName) {
  if (requestingPermission) return;
  requestingPermission = true;
  try {
    if (refreshPromise) await refreshPromise;
    const result = await notchany.invoke(eventName, null);
    if (!render(result)) {
      showToast(result?.error?.message || t('permission_request_failed'));
      return;
    }
    if (result.state?.message) showToast(result.state.message, 4200);
  } finally {
    requestingPermission = false;
  }
}

$('refresh').addEventListener('click', refresh);
$('permissionButton').addEventListener('click', () => requestPermission('request_accessibility'));
$('captureButton').addEventListener('click', () => requestPermission('request_screen_capture'));

applyI18n();

notchany.addEventListener('statechange', event => render(event.state));
notchany.addEventListener('visibilitychange', () => {
  clearInterval(timer);
  timer = 0;
  if (notchany.visible) {
    refresh();
    timer = setInterval(refresh, FALLBACK_REFRESH_MS);
  }
});

if (notchany.state) render(notchany.state);
if (notchany.visible) {
  refresh();
  timer = setInterval(refresh, FALLBACK_REFRESH_MS);
}

new ResizeObserver(updateResponsiveLayout).observe(document.documentElement);
